import importlib.util
spec=importlib.util.spec_from_file_location('entry','/app/submission/entry.py')
entry=importlib.util.module_from_spec(spec); spec.loader.exec_module(entry)
LEVELS=['I','H','Z','A']
def rnd_hex(n=None):
    n=random.randrange(0,5) if n is None else n
    return ''.join(random.choice('0123456789abcdef') for _ in range(n*2))
def rnd_range():
    lo=random.randrange(0,20); hi=random.randrange(0,20)
    return [lo,hi]
def rnd_ranges():
    return [rnd_range() for _ in range(random.randrange(0,4))]
def rnd_frame():
    ty=random.choice(['PADDING','PING','ACK','CRYPTO','STREAM','RESET_STREAM','STOP_SENDING','CLOSE','HANDSHAKE_DONE','UNKNOWN'])
    if ty in ('PADDING','PING','HANDSHAKE_DONE','UNKNOWN'): return {'type':ty}
    if ty=='ACK': return {'type':ty,'ranges':rnd_ranges()}
    if ty=='CRYPTO': return {'type':ty,'offset':random.randrange(0,12),'data_hex':rnd_hex()}
    if ty=='STREAM': return {'type':ty,'id':random.choice([0,2,4,6,8,10,12,14,1,3]),'offset':random.randrange(0,12),'data_hex':rnd_hex(),'fin':random.choice([True,False])}
    if ty=='RESET_STREAM': return {'type':ty,'id':random.choice([0,2,4,6,8,10,1,3]),'final_size':random.randrange(0,15)}
    if ty=='STOP_SENDING': return {'type':ty,'id':random.choice([0,2,4,6,8,1,3])}
    if ty=='CLOSE': return {'type':ty,'app':random.choice([True,False]),'code':random.randrange(0,5)}
def rnd_packet():
    return {'level':random.choice(LEVELS),'pn':random.randrange(0,8),'auth':random.choice([True,False]),
            'frames':[rnd_frame() for _ in range(random.randrange(0,5))]}
def rnd_event(t):
    op=random.choice(['datagram','datagram','datagram','key','tick'])
    if op=='key': return {'t':t,'op':'key','level':random.choice(LEVELS),'action':random.choice(['install','discard'])}
    if op=='tick': return {'t':t,'op':'tick'}
    n=random.randrange(1,5)
    return {'t':t,'op':'datagram','bytes':random.choice([0,100,1199,1200,1300]),'packets':[rnd_packet() for _ in range(n)]}
def rnd_config():
